def solve(A):
    A.sort()
    n = len(A)
    dp = [float('inf')] * n
    dp[0] = 0
    for i in range(1, n):
        for j in range(i):
            dp[i] = min(dp[i], dp[j] + abs(A[i] - A[j]))
    return dp[n-1]

